    def parse_more(self, i):
        """
        Parses the thousand/million/billion suffix based on the index
        :param i: int, the index representing the magnitude (thousand, million, billion)
        :return: str, the corresponding suffix for the magnitude
        >>> formatter = NumberWordFormatter()
        >>> formatter.parse_more(1)
        "THOUSAND"
        """
        magnitude = i
        if magnitude < 100:
            return self.NUMBER_MORE[magnitude]
        elif magnitude < 1000:
            return self.NUMBER_SUFFIX[magnitude/100]
        elif magnitude < 1000000:
            return self.NUMBER_SUFFIX[magnitude/1000]
        elif magnitude < 1000000000:
            return self.NUMBER_SUFFIX[magnitude/1000000]
        else:
            return self.NUMBER_SUFFIX[magnitude/1000000000]

